pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // require non-empty _tos to avoid revert in reference
        vm.assume(_tos.length > 0);
        // call transfer and capture return value
        bool result = c.transfer(from, caddress, _tos, v);
        // The reference always returns true; the mutant returns false
        assertTrue(result);
    }
}

